DO $$ DECLARE d text; old_text text := 'FROM public.spend_notices WHERE line_id=l.id ORDER BY created_at DESC,id DESC LIMIT 1'; new_text text := 'FROM public.spend_notices n0 WHERE n0.line_id=l.id AND EXISTS(SELECT 1 FROM public.spend_logs a WHERE a.card_id=c.id AND a.action=''adjustment'' AND a.details->>''line_id''=l.id::text AND a.created_at=n0.created_at) ORDER BY n0.created_at DESC,n0.id DESC LIMIT 1'; BEGIN SELECT pg_get_functiondef('public.spend_pending_adjustments(boolean)'::regprocedure) INTO d; IF position(old_text IN d)=0 THEN RAISE EXCEPTION 'Pending function definition mismatch'; END IF; EXECUTE replace(d,old_text,new_text); END $$;